from IQEngine.interface import AbstractPlugin
from IQEngine.const import AccountType, RunType
from IQEngine.api.api_extra import api_method
from IQEngine.plugins.plugin_system_accounts.account_model import StockAccount, FutureAccount, BenchmarkAccount, OptionAccount, LiveFutureAccount, LiveOptionAccount, LiveHksAccount
from IQEngine.plugins.plugin_system_accounts.position_model import StockPosition, FuturePosition, OptionPosition, LiveStockPosition, LiveFuturePosition, LiveOptionPosition, LiveHksPosition
from IQEngine.plugins.plugin_system_accounts.api import api_future, api_stock, api_option
class AccountPlugin(AbstractPlugin):
    def setup(self, engine):
        StockPosition.STOCK_T1 = engine.config.strategy.stock_t1
        engine.set_account_model(AccountType.STOCK.value, StockAccount)
        if (engine.config.strategy.run_type == RunType.TRADING):
            engine.set_position_model(AccountType.STOCK.value, LiveStockPosition)
        else:
            engine.set_position_model(AccountType.STOCK.value, StockPosition)
        engine.set_account_model(AccountType.RZRQ.value, StockAccount)
        engine.set_position_model(AccountType.RZRQ.value, StockPosition)
        if (engine.config.strategy.run_type == RunType.TRADING):
            engine.set_account_model(AccountType.FUTURE.value, LiveFutureAccount)
            engine.set_position_model(AccountType.FUTURE.value, LiveFuturePosition)
            engine.set_account_model(AccountType.OPTION.value, LiveOptionAccount)
            engine.set_position_model(AccountType.OPTION.value, LiveOptionPosition)
            engine.set_account_model(AccountType.HKS.value, LiveHksAccount)
            engine.set_position_model(AccountType.HKS.value, LiveHksPosition)
        else:
            engine.set_account_model(AccountType.FUTURE.value, FutureAccount)
            engine.set_position_model(AccountType.FUTURE.value, FuturePosition)
            engine.set_account_model(AccountType.OPTION.value, OptionAccount)
            engine.set_position_model(AccountType.OPTION.value, OptionPosition)
        engine.set_account_model(AccountType.BENCHMARK.value, BenchmarkAccount)
        engine.set_position_model(AccountType.BENCHMARK.value, StockPosition)
        if (AccountType.FUTURE.value in engine.config.strategy.accounts):
            for export_name in api_future.__all__:
                api_method(getattr(api_future, export_name))
    def cleanup(self, exit_code, exception=None):
        return None
    def interface(self):
        return self
def load_plugin():
    return AccountPlugin()
